        for (typ, k) in walls:
            g = np.zeros(3 * n)
            if typ == 0: g[3 * k] = 1.0; g[3 * k + 2] = -1.0
            elif typ == 1: g[3 * k] = -1.0; g[3 * k + 2] = -1.0
            elif typ == 2: g[3 * k + 1] = 1.0; g[3 * k + 2] = -1.0
            else: g[3 * k + 1] = -1.0; g[3 * k + 2] = -1.0
            grads.append(g)
        return grads

    def resid(w):
        z = w[:3 * n]
        lam = w[3 * n:]
        r1 = active_vals(z)
        grads = active_grads(z)
        gobj = np.zeros(3 * n); gobj[2::3] = -1.0
        s = gobj.copy()
        for m in range(n_act):
            s = s + lam[m] * grads[m]
        return np.concatenate([r1, s])

    w0 = np.concatenate([v.copy(), np.full(n_act, 0.1)])
    try:
        res = least_squares(resid, w0, method='lm', max_nfev=300,
                            xtol=1e-15, ftol=1e-15, gtol=1e-15)
    except Exception:
        return None
    if _pt() > deadline:
        return None
    if not np.all(np.isfinite(res.x)):
        return None
    if np.linalg.norm(res.fun) > 1e-10:
        return None
    z = res.x[:3 * n]
    lam = res.x[3 * n:]
    if np.any(lam < -1e-9):
        return None
    xx = z[0::3]; yy = z[1::3]; rr = z[2::3]
    if np.any(rr <= 0):
        return None
    if _worst_violation(xx, yy, rr) > 1e-9:
        return None
    return z


def _active_set(v, n, tol=1e-7):
    """Return list of active constraints as ('p',i,j) or ('w',typ,k)."""
    x = v[0::3]; y = v[1::3]; r = v[2::3]
    iu = np.triu_indices(n, 1)
    ii = iu[0]; jj = iu[1]
    dx = x[ii] - x[jj]; dy = y[ii] - y[jj]
    d = np.sqrt(dx * dx + dy * dy)
    gap = d - (r[ii] + r[jj])
    A = []
    for m in range(len(ii)):
        if gap[m] > -tol:
            A.append(('p', int(ii[m]), int(jj[m])))
    for k in range(n):
        if x[k] - r[k] < tol: A.append(('w', 0, k))
        if 1 - x[k] - r[k] < tol: A.append(('w', 1, k))
        if y[k] - r[k] < tol: A.append(('w', 2, k))
        if 1 - y[k] - r[k] < tol: A.append(('w', 3, k))
    return A


def _eq_con(con, n):
    typ = con[0]
    if typ == 'p':
        i, j = con[1], con[2]
        def f(v):
            dx = v[3 * i] - v[3 * j]; dy = v[3 * i + 1] - v[3 * j + 1]
            return np.array([np.sqrt(dx * dx + dy * dy) - v[3 * i + 2] - v[3 * j + 2]])
        def jac(v):
            dx = v[3 * i] - v[3 * j]; dy = v[3 * i + 1] - v[3 * j + 1]
            dd = np.sqrt(dx * dx + dy * dy) + 1e-300
            g = np.zeros((1, 3 * n))
            g[0, 3 * i] = dx / dd; g[0, 3 * i + 1] = dy / dd; g[0, 3 * i + 2] = -1.0
            g[0, 3 * j] = -dx / dd; g[0, 3 * j + 1] = -dy / dd; g[0, 3 * j + 2] = -1.0
            return g
        return {'type': 'eq', 'fun': f, 'jac': jac}
    else:
        k = con[2]; t = con[1]
        def f(v):
            x = v[3 * k]; y = v[3 * k + 1]; r = v[3 * k + 2]
            if t == 0: return np.array([x - r])
            if t == 1: return np.array([1 - x - r])
            if t == 2: return np.array([y - r])
            return np.array([1 - y - r])
        def jac(v):
            g = np.zeros((1, 3 * n))
            if t == 0: g[0, 3 * k] = 1.0; g[0, 3 * k + 2] = -1.0
            elif t == 1: g[0, 3 * k] = -1.0; g[0, 3 * k + 2] = -1.0
            elif t == 2: g[0, 3 * k + 1] = 1.0; g[0, 3 * k + 2] = -1.0
            else: g[0, 3 * k + 1] = -1.0; g[0, 3 * k + 2] = -1.0
            return g
        return {'type': 'eq', 'fun': f, 'jac': jac}


def construct(budget_seconds, start):
    n = 26
    t0 = _pt()
    deadline = t0 + budget_seconds * 0.80

    if start is not None:
        base = np.asarray(start, dtype=float).reshape(n, 3).copy()
    else:
        base = np.zeros((n, 3))
        cols, rows = 5, 6
        idx = 0
        for j in range(rows):
            for i in range(cols):
                if idx >= n:
                    break
                base[idx] = [(i + 0.5) / cols, (j + 0.5) / rows, 0.06]
                idx += 1

    base[:, 2] = np.maximum(base[:, 2], 1e-4)
    base[:, 0] = np.clip(base[:, 0], base[:, 2], 1 - base[:, 2])
    base[:, 1] = np.clip(base[:, 1], base[:, 2], 1 - base[:, 2])

    cons = _make_cons(n)
    v = base.ravel().copy()
    pol = _slsqp(v, cons, maxiter=600, ftol=1e-13)
    if pol is not None and _score(pol, n) > _score(v, n):
        v = pol
    best_v = v.copy()
    best_score = _score(best_v, n)
    if not np.isfinite(best_score):
        best_v = base.ravel().copy()
        best_score = float(np.sum(best_v[2::3]))

    rng = np.random.default_rng(12345)

    while _pt() < deadline:
        cur = best_v.reshape(n, 3).copy()
        xy = cur[:, :2].copy()

        mode = rng.random()
        if mode < 0.5:
            sigma = rng.uniform(0.003, 0.02)
            xy_new = xy + rng.normal(0, sigma, size=xy.shape)
        elif mode < 0.85:
            ci = int(rng.integers(n))
            R = rng.uniform(0.15, 0.35)
            d = np.sqrt((xy[:, 0] - xy[ci, 0]) ** 2 + (xy[:, 1] - xy[ci, 1]) ** 2)
            sel = d <= R
            sigma = rng.uniform(0.005, 0.03)
            xy_new = xy.copy()
            xy_new[sel] += rng.normal(0, sigma, size=(sel.sum(), 2))
        else:
            k = int(rng.integers(1, 4))
            idx = rng.choice(n, size=k, replace=False)
            sigma = rng.uniform(0.01, 0.05)
            xy_new = xy.copy()
            xy_new[idx] += rng.normal(0, sigma, size=(k, 2))
        xy_new = np.clip(xy_new, 1e-4, 1 - 1e-4)

        r_new = _max_radii_for_positions(xy_new[:, 0], xy_new[:, 1], n)
        if r_new is None:
            continue
        cand = np.column_stack([xy_new, r_new])
        vc = cand.ravel().copy()
        rc = _slsqp(vc, cons, maxiter=300, ftol=1e-12)
        if rc is None:
            continue
        sc = _score(rc, n)
        if np.isfinite(sc) and sc > best_score + 1e-10:
            best_v = rc
            best_score = sc

    scale_deadline = t0 + budget_seconds * 0.90
    try:
        cur = best_v.reshape(n, 3).copy()
        xy = cur[:, :2].copy()
        r = cur[:, 2].copy()

        def f(z):
            x = z[0::2]; y = z[1::2]
            iu = np.triu_indices(n, 1)
            i = iu[0]; j = iu[1]
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = np.sqrt(dx * dx + dy * dy)
            vp = np.maximum(0.0, (r[i] + r[j]) - d)
            vw = (np.maximum(0.0, r - x) ** 2 + np.maximum(0.0, x + r - 1.0) ** 2
                  + np.maximum(0.0, r - y) ** 2 + np.maximum(0.0, y + r - 1.0) ** 2)
            return float(np.sum(vp * vp) + np.sum(vw))

        lo, hi = 1.0, 1.12
        best_t = 1.0
        best_xy = xy.copy()
        for _ in range(14):
            if _pt() > scale_deadline:
                break
            mid = 0.5 * (lo + hi)
            res = minimize(f, xy.ravel(), method='L-BFGS-B',
                           options={'maxiter': 200, 'ftol': 1e-16})
            if np.isfinite(res.fun) and res.fun < 1e-12:
                lo = mid; best_t = mid; best_xy = res.x.reshape(n, 2)
            else:
                hi = mid
        if best_t > 1.0:
            cand = np.column_stack([best_xy, best_t * r])
            rc = _slsqp(cand.ravel().copy(), cons, maxiter=600, ftol=1e-14)
            if rc is not None:
                sc = _score(rc, n)
                if np.isfinite(sc) and sc > best_score:
                    best_v = rc
                    best_score = sc
    except Exception:
        pass

    # --- Active-set pivoting: swap one active constraint for an inactive pair ---
    pivot_deadline = t0 + budget_seconds * 0.85
    try:
        while _pt() < pivot_deadline:
            A = _active_set(best_v, n, tol=1e-7)
            if len(A) == 0:
                break
            x = best_v[0::3]; y = best_v[1::3]; r = best_v[2::3]
            iu = np.triu_indices(n, 1)
            ii = iu[0]; jj = iu[1]
            dx = x[ii] - x[jj]; dy = y[ii] - y[jj]
            d = np.sqrt(dx * dx + dy * dy)
            gap = d - (r[ii] + r[jj])
            inactive = [(int(ii[m]), int(jj[m])) for m in range(len(ii))
                        if gap[m] > 1e-7 and gap[m] < 0.1]
            if len(inactive) == 0:
                break
            # try a few random pivots
            improved = False
            tries = 0
            while tries < 8 and _pt() < pivot_deadline:
                tries += 1
                k = int(rng.integers(len(A)))
                pi_, pj_ = inactive[int(rng.integers(len(inactive)))]
                newA = [c for m, c in enumerate(A) if m != k]
                newA.append(('p', pi_, pj_))
                eqs = [_eq_con(c, n) for c in newA]
                allcons = eqs + cons
                res = _slsqp(best_v.copy(), allcons, maxiter=200, ftol=1e-13)
                if res is None:
                    continue
                sc = _score(res, n)
                if np.isfinite(sc) and sc > best_score + 1e-12:
                    best_v = res
                    best_score = sc
                    improved = True
                    break
            if not improved:
                break
    except Exception:
        pass

    if _pt() < t0 + budget_seconds * 0.97:
        pol2 = _slsqp(best_v.copy(), cons, maxiter=500, ftol=1e-14)
        if pol2 is not None:
            sc2 = _score(pol2, n)
            if np.isfinite(sc2) and sc2 > best_score:
                best_v = pol2
                best_score = sc2

    kkt_deadline = t0 + budget_seconds * 0.95
    try:
        z = _kkt_refine(best_v.copy(), n, kkt_deadline)
        if z is not None:
            sc_z = _score(z, n)
            if np.isfinite(sc_z) and sc_z >= best_score - 1e-12:
                best_v = z
                best_score = max(best_score, sc_z)
    except Exception:
        pass

    result = best_v.reshape(n, 3).copy()
    result[:, 2] = np.maximum(result[:, 2], 1e-6)

    x = result[:, 0].copy()
    y = result[:, 1].copy()
    r = result[:, 2].copy()

    v0 = _worst_violation(x, y, r)
    if v0 <= 0.0:
        s = 1.0
    else:
        lo_s, hi_s = 1.0 - 1e-6, 1.0
        s = lo_s
        for _ in range(50):
            mid = 0.5 * (lo_s + hi_s)
            if _worst_violation(x, y, mid * r) <= 0.0:
                lo_s = mid
                s = mid
            else:
                hi_s = mid
    result[:, 2] = s * r

    if _worst_violation(result[:, 0], result[:, 1], result[:, 2]) > 0.0:
        result[:, 2] *= (1 - 1e-14)

    return result
